pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HelperReceiver helper;

    function setUp() public { 
        c = new C();
        helper = new HelperReceiver();
    }

    // fuzzed params: from address, array of recipients length, index variation and value
    function testFuzz_property(address from, uint8 tosLen, uint256 v) public {
        // keep tosLen reasonable but allow 1..10
        uint256 len = bound(tosLen, 1, 10);

        // build dynamic address array filled with the helper contract address
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
        }

        // The call performed by C is a low-level call to the provided caddress.
        // We deploy a helper that always accepts the call and returns successfully.
        // Because the helper never reverts, transfer should complete and return true in the reference.

        bool ok;
        try c.transfer(from, address(helper), tos, v) returns (bool ret) {
            // capture whether call returned true
            ok = ret;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (tos length >=1), the reference returns true.
        // The mutant that returns false at the end will make this assertion fail for some inputs.
        assertTrue(ok);
    }
}

// Helper that accepts the low-level call and returns non-reverting success
contract HelperReceiver {
    // match the selector transferFrom(address,address,uint256)
    // function signature isn't actually enforced by low-level call, but we include a compatible function
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        return true;
    }

    // fallback to accept any encoded selector and return success
    fallback() external payable {
        // do nothing, just accept the call successfully
    }

    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the array length and a value; we must deploy an adversarial callee that will fail on specific indices
    function testFuzz_property(uint256 failIndex, uint256 len) public {
        // keep domain wide but sensible
        len = bound(len, 1, 10); // _tos.length must be > 0 per require
        // failIndex may be out of range; bound it to allow failing behavior inside array
        failIndex = bound(failIndex, 0, len - 1);

        // build addresses array of helpers: all succeed except the one at failIndex will revert
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            if (i == failIndex) {
                tos[i] = address(new Reverter());
            } else {
                tos[i] = address(new Succeeder());
            }
        }

        address caller = address(0xBEEF);
        // call transfer and capture whether it returns (does not revert) and its return value
        bool ok;
        try c.transfer(caller, address(c), tos, 1) returns (bool ret) {
            ok = ret;
        } catch {
            // reverted
            ok = false;
        }

        // GENERAL RULE (assertion): The reference implementation always returns false (i.e., reverts or returns false)
        // if any callee reverts during the loop; since our adversarial setup makes one callee revert at failIndex,
        // the correct contract should revert (so ok==false). The mutant that returns early on first success may
        // incorrectly return true when a later callee would revert. Therefore assertTrue(ok == false).
        assertTrue(ok == false);
    }
}

// helper that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// helper that always succeeds for arbitrary selector/data
contract Succeeder {
    fallback() external payable {
        // succeed and return empty
    }
}
